// The review focus: the bridge's rules are the real v2 aggregator's. ScoringLib's and AggregatorLib's
// answers here came from the real libraries (test/fixtures/scoring-lib.vectors.json, generated by
// test/fixtures/gen-scoring-vectors.cjs from verdikta-dispatcher's `beacon` branch at the commit it
// names); the rest follows ReputationAggregator.fulfill, closeCommits, promote and _finalize line by
// line, each case naming what the real contract does.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { AbiCoder, keccak256 } from 'ethers';

import {
  AggregatorRound, REAL_CONFIG, SMALL_JURY, aggregate, bestCluster, classifyOne, commitHashOf, commitmentOf, mPlusOf, normalize, parseCidSalt,
  pickPromoted, promoteSeedOf, tieOrder,
} from '../src/aggregatorRound.js';

const vectors = JSON.parse(fs.readFileSync(new URL('./fixtures/scoring-lib.vectors.json', import.meta.url), 'utf8'));
const OPERATOR = '0x0000000000000000000000000000000000000001';
const AGG = `0x${'00'.repeat(31)}07`;
const FEE = 120000000000000n;
const big = (a) => a.map((v) => v.map(BigInt));
const CID = (n) => `Qm${String(n).repeat(44)}`.slice(0, 46);
const SALT = 'be4cdf395cfcfd8b385f0123456789ab';
const SEED = keccak256('0x01');

const newRound = (o = {}) => new AggregatorRound({ aggId: AGG, operatorOf: () => OPERATOR, fee: FEE, ...o });
/** What an honest arbiter commits for this vector and salt: the EA's number. */
const commitOf = (vector, salt = SALT) => BigInt(`0x${commitmentOf(AGG, OPERATOR, vector, BigInt(`0x${salt}`))}`);
/** Commits from slots 0.. in order; then promote. Returns the reveal requests. */
function committed(round, list, seed = SEED) {
  list.forEach((v, slot) => { round.fulfill(slot, [commitOf(v)], ''); });
  if (round.phase === 'commit') round.close();
  return round.promote(seed);
}

test('the real libraries\' answers: bestCluster (nearest-neighbour, and the exact 1-D window)', () => {
  assert.ok(vectors.bestCluster.length >= 30);
  assert.ok(vectors.bestCluster.some((t) => t.v[0].length === 1), 'one-number cases too');
  for (const t of vectors.bestCluster) assert.deepEqual(bestCluster(big(t.v), t.p), t.inCluster, JSON.stringify(t));
});

test('the real libraries\' answers: tieOrder, pickPromoted, classifyOne', () => {
  for (const t of vectors.tieOrder) assert.deepEqual(tieOrder(t.seed, t.ids), t.perm, JSON.stringify(t));
  assert.ok(vectors.pickPromoted.length >= 5);
  for (const t of vectors.pickPromoted) assert.deepEqual(pickPromoted(t.committed, t.m, t.seed), t.chosen, JSON.stringify(t));
  for (const t of vectors.classifyOne) assert.equal(classifyOne(t.x.map(BigInt), t.med.map(BigInt), BigInt(t.spread)), t.q, JSON.stringify(t));
});

test('the real libraries\' answers: aggregate (normalization, the seeded cluster, the floored mean, the classes)', () => {
  for (const t of vectors.aggregate) {
    const got = aggregate(big(t.v), t.p, BigInt(t.floor), t.seed, t.ids);
    assert.deepEqual(got.inCl, t.inCl, JSON.stringify(t));
    assert.deepEqual(got.agg.map(String), t.agg, JSON.stringify(t));
    assert.deepEqual(got.codes, t.codes, JSON.stringify(t));
    assert.deepEqual(got.med.map(String), t.med);
    assert.equal(got.spread.toString(), t.spread);
  }
});

test('the real libraries\' answers: parseCidSalt ("<cid>:<32 hex>")', () => {
  for (const t of vectors.parseCidSalt) {
    const got = parseCidSalt(t.packed);
    assert.equal(got !== null, t.ok, t.packed);
    if (t.ok) {
      assert.equal(got.cid, t.cid);
      assert.equal(got.salt.toString(), t.salt);
    }
  }
});

test('normalization ties go to the LONGER length (v1 took the shorter)', () => {
  assert.deepEqual(normalize(big([[1, 2], [3], [4, 5], [6]])), big([[1, 2], [3, 0], [4, 5], [6, 0]]));
});

test('the configuration is the real contract\'s default, the jury Small\'s, and maxTotalFee is max(eff, floor) x (K + B x P) + eff x (draw + promote)', () => {
  assert.deepEqual([SMALL_JURY.K, SMALL_JURY.M, SMALL_JURY.N, SMALL_JURY.P, SMALL_JURY.timeout, REAL_CONFIG.bonus], [6, 5, 4, 3, 300, 3]);
  assert.deepEqual([REAL_CONFIG.maxJury, REAL_CONFIG.maxTimeout, REAL_CONFIG.tPlus, REAL_CONFIG.revealWindow], [50, 3600, 155, 120]);
  for (const k of ['k', 'm', 'n', 'p', 'responseTimeoutSeconds']) assert.equal(REAL_CONFIG[k], undefined, `${k} is the request's on v2, not the aggregator's`);
  assert.equal(mPlusOf(), 6);
  assert.equal(AggregatorRound.required(FEE), FEE * 18n);
  assert.equal(AggregatorRound.required(FEE, { minFee: FEE * 2n }), FEE * 2n * 15n + FEE * 3n);
  assert.equal(AggregatorRound.required(FEE, { beacons: 2 }), FEE * 20n);
  // maxTotalFee(maxFee, minFee, withBeacons, K, P): the jury's K and P, e.g. Jumbo's 50 and 17 with its beacons
  assert.equal(AggregatorRound.required(FEE, { K: 50, P: 17, beacons: 2 }), FEE * BigInt(50 + 3 * 17 + 2) + FEE * 3n);
  assert.equal(AggregatorRound.required(FEE, { K: 12, P: 5 }), FEE * 27n + FEE * 3n);
});

test('a round runs by its own jury: K slots, M+ and M from K and M, M promoted, N counted, P clustered, base fees x K', () => {
  const jury = { K: 12, M: 9, N: 7, P: 5, timeout: 600 };
  assert.equal(mPlusOf(jury), 11, 'M + ceil((K - M) / 2)');
  assert.equal(mPlusOf({ K: 50, M: 38, N: 27, P: 17, timeout: 600 }), 44);
  const r = new AggregatorRound({ aggId: AGG, operatorOf: () => OPERATOR, fee: FEE, jury });
  assert.equal(r.baseCredited, FEE * 12n);
  const v = [0n, 1000000n];
  for (let s = 0; s < 10; s += 1) assert.equal(r.fulfill(s, [commitOf(v, SALT.replace(/.$/, String(s % 10)))], '').kind, 'commit', `commit ${s + 1} of M+ = 11`);
  assert.equal(r.fulfill(10, [commitOf(v, SALT.replace(/.$/, 'a'))], '').kind, 'closed');
  const seed = promoteSeedOf(AGG, keccak256('0x02'));
  const reveals = r.promote(seed);
  assert.equal(reveals.length, 9, 'M promoted');
  assert.deepEqual(reveals.map((x) => x.slot), pickPromoted([...Array(11).fill(true), false], 9, seed));
  let last;
  for (const [i, { slot }] of reveals.slice(0, 7).entries()) {
    last = r.fulfill(slot, v, `${CID(slot)}:${SALT.replace(/.$/, slot === 10 ? 'a' : String(slot))}`);
    assert.equal(last.kind, i < 6 ? 'reveal' : 'finalized', `reveal ${i + 1} of N = 7`);
  }
  assert.equal(last.clustered, 5, 'P clustered');
  assert.equal(r.bonusCredited, FEE * 3n * 5n);
  // after T+, the window closes at M commits of this jury, not Small's 5
  const late = new AggregatorRound({ aggId: AGG, operatorOf: () => OPERATOR, fee: FEE, jury });
  for (let s = 0; s < 8; s += 1) assert.equal(late.fulfill(s, [commitOf(v)], '', { pastWindow: true }).kind, 'commit');
  assert.equal(late.fulfill(8, [commitOf(v)], '', { pastWindow: true }).kind, 'closed');
});

test('the commitment: keccak256(abi.encode(aggId, operator, scores, salt)), all 32 bytes, bound to the round', () => {
  const scores = [0n, 0n, 0n, 0n, 700000n, 300000n];
  const salt = BigInt(`0x${SALT}`);
  const encoded = AbiCoder.defaultAbiCoder().encode(['bytes32', 'address', 'uint256[]', 'uint256'], [AGG, OPERATOR, scores, salt]);
  assert.equal(commitmentOf(AGG, OPERATOR, scores, salt), keccak256(encoded).slice(2));
  assert.notEqual(commitmentOf(`0x${'00'.repeat(31)}08`, OPERATOR, scores, salt), commitmentOf(AGG, OPERATOR, scores, salt));
  assert.equal(commitHashOf(5n), '0'.repeat(63) + '5');
  assert.equal(commitHashOf(0n), null);
});

test('a commit is one number with no CID; zero and repeats are ignored; the M+-th closes the window', () => {
  const r = newRound();
  const v = [0n, 1000000n];
  assert.deepEqual(r.fulfill(0, [0n], ''), { kind: 'ignored', reason: 'zero commit' });
  assert.equal(r.fulfill(0, [commitOf(v)], '').kind, 'commit');
  assert.deepEqual(r.fulfill(0, [commitOf(v)], ''), { kind: 'ignored', reason: 'duplicate commit' });
  for (let s = 1; s < 5; s += 1) assert.equal(r.fulfill(s, [commitOf(v)], '').kind, 'commit');
  assert.equal(r.fulfill(5, [commitOf(v)], '').kind, 'closed', 'M+ = 6 of K = 6');
  assert.deepEqual(r.fulfill(5, [commitOf(v)], ''), { kind: 'ignored', reason: 'commit after the window closed' });
});

test('after T+, the commit that brings the count to M closes the window, as the real fulfill does', () => {
  const r = newRound();
  const v = [0n, 1000000n];
  for (let s = 0; s < 4; s += 1) assert.equal(r.fulfill(s, [commitOf(v)], '', { pastWindow: true }).kind, 'commit');
  assert.equal(r.fulfill(4, [commitOf(v)], '', { pastWindow: true }).kind, 'closed');
});

test('closeCommits after T+: only with at least M commits', () => {
  const r = newRound();
  const v = [0n, 1000000n];
  for (let s = 0; s < 4; s += 1) r.fulfill(s, [commitOf(v)], '');
  assert.equal(r.close(), null);
  r.fulfill(4, [commitOf(v)], '');
  assert.deepEqual(r.close(), { kind: 'closed' });
  assert.equal(r.close(), null);
});

test('promote draws M of the commits with the promote seed, and asks each for "2:<64 hex commitment>"', () => {
  const r = newRound();
  const v = [0n, 1000000n];
  for (let s = 0; s < 6; s += 1) r.fulfill(s, [commitOf(v, SALT.replace(/.$/, String(s)))], '');
  const seed = promoteSeedOf(AGG, keccak256('0x02'));
  const reveals = r.promote(seed);
  assert.equal(reveals.length, SMALL_JURY.M);
  assert.deepEqual(reveals.map((x) => x.slot), pickPromoted(Array(6).fill(true), 5, seed));
  for (const x of reveals) {
    assert.match(x.cid, /^2:[0-9a-f]{64}$/);
    assert.equal(x.cid.slice(2), r.commitHash.get(x.slot));
  }
  assert.throws(() => r.promote(seed), /WrongPhase/);
});

test('a reveal before promotion, from a slot not promoted, or with no CID, is not taken (no revert on v2)', () => {
  const r = newRound();
  const v = [1n, 999999n];
  r.fulfill(0, [commitOf(v)], '');
  assert.equal(r.fulfill(0, v, `${CID(1)}:${SALT}`).reason, 'not in the reveal phase');
  const r2 = newRound();
  const reveals = committed(r2, [v, v, v, v, v, v]);
  const out = [0, 1, 2, 3, 4, 5].find((s) => !reveals.some((x) => x.slot === s));
  assert.equal(r2.fulfill(out, v, `${CID(1)}:${SALT}`).reason, 'not promoted');
  // one value with no CID is a commit's shape: in the reveal phase, ignored
  assert.equal(r2.fulfill(reveals[0].slot, [5n], '').reason, 'commit after the window closed');
});

test('a one-value reveal has a CID, so it is a reveal; a one-number round finalizes on the exact 1-D cluster', () => {
  const r = newRound();
  const values = [[40n], [41n], [42n], [1000000n], [43n], [44n]];
  const reveals = committed(r, values);
  let last;
  for (const { slot } of reveals) last = r.fulfill(slot, values[slot], `${CID(slot)}:${SALT}`);
  // N = 4 of the 5 promoted are counted; the fifth is late
  assert.equal(r.responses.length, 4);
  const counted = r.responses.map((x) => x.likelihoods);
  const expected = aggregate(counted, 3, REAL_CONFIG.spreadFloor, r.sealedHash, r.responses.map((x) => x.slot));
  assert.deepEqual(r.result.likelihoods, expected.agg);
  assert.equal(r.result.likelihoods.length, 1);
  assert.ok(['late', 'finalized'].includes(last.kind));
});

test('a reveal must open its commitment: the wrong scores, salt, operator or round are not taken', () => {
  const v = [0n, 0n, 0n, 0n, 700000n, 300000n];
  const r = newRound();
  const reveals = committed(r, [v, v, v, v, v, v]);
  const slot = reveals[0].slot;
  assert.equal(r.fulfill(slot, [0n, 0n, 0n, 0n, 700001n, 299999n], `${CID(1)}:${SALT}`).reason, 'hash mismatch');
  assert.equal(r.fulfill(slot, v, `${CID(1)}:${'0'.repeat(32)}`).reason, 'hash mismatch');
  const other = newRound({ operatorOf: () => '0x0000000000000000000000000000000000000002' });
  const r3 = committed(other, [v, v, v, v, v, v]);
  assert.equal(other.fulfill(r3[0].slot, v, `${CID(1)}:${SALT}`).reason, 'hash mismatch');
  assert.equal(r.responses.length, 0);
});

test('reveals past the real limits are not taken: too many scores, a CID string over 133 bytes, a bad salt, a repeat', () => {
  const r = newRound();
  const v = [0n, 1000000n];
  const [{ slot }] = committed(r, [v, v, v, v, v, v]);
  assert.equal(r.fulfill(slot, new Array(21).fill(0n), `${CID(1)}:${SALT}`).reason, 'bad length');
  assert.equal(r.fulfill(slot, v, `${'a'.repeat(101)}:${SALT}`).reason, 'CID too long');
  assert.equal(r.fulfill(slot, v, `${CID(1)}:nothex`).reason, 'bad CID and salt');
  assert.equal(r.fulfill(slot, v, `${CID(1)}:${SALT}`).kind, 'reveal');
  assert.equal(r.fulfill(slot, v, `${CID(1)}:${SALT}`).reason, 'duplicate reveal');
});

test('the N-th counted reveal finalizes: the cluster\'s floored mean, its CIDs comma-joined in reveal order, the rest late', () => {
  const far = [0n, 0n, 0n, 0n, 1000000n, 0n];
  const a = [0n, 0n, 0n, 0n, 700000n, 300000n];
  const b = [0n, 0n, 0n, 0n, 700001n, 299999n];
  const r = newRound();
  const list = [far, a, b, a, b, a];
  const reveals = committed(r, list);
  const results = reveals.map(({ slot }) => r.fulfill(slot, list[slot], `${CID(slot)}:${SALT}`));
  assert.deepEqual(results.map((x) => x.kind), ['reveal', 'reveal', 'reveal', 'finalized', 'late']);
  const fin = results[3];
  const counted = r.responses;
  const expect = aggregate(counted.map((x) => x.likelihoods), 3, REAL_CONFIG.spreadFloor, r.sealedHash, counted.map((x) => x.slot));
  assert.deepEqual(fin.likelihoods, expect.agg);
  assert.equal(fin.clustered, 3);
  assert.equal(fin.justifications, counted.filter((_, i) => expect.inCl[i]).map((x) => x.cid).join(','));
  assert.equal(r.fulfill(reveals[4].slot, list[reveals[4].slot], `${CID(1)}:${SALT}`).reason, 'duplicate reveal');
  assert.equal(r.fulfill(0, [commitOf(a)], '').reason, 'commit after the window closed');
});

test('nothing lands after the deadline', () => {
  const r = newRound();
  assert.deepEqual(r.fulfill(0, [commitOf([1n, 2n])], '', { late: true }), { kind: 'ignored', reason: 'past the deadline' });
  assert.equal(r.commitHash.size, 0);
});

test('scores above the real ceiling are clamped before aggregation', () => {
  const huge = [10n ** 40n, 1n];
  const r = newRound();
  const reveals = committed(r, [huge, huge, huge, huge, huge, huge]);
  let last;
  for (const { slot } of reveals.slice(0, 4)) last = r.fulfill(slot, huge, `${CID(slot)}:${SALT}`);
  assert.deepEqual(last.likelihoods, [10n ** 34n, 1n]);
});

test('the money, on every exit path: base to all K at the draw; bonus only to the clustered; the rewards; the rest comes back', () => {
  const required = AggregatorRound.required(FEE);
  const failed = newRound();
  assert.equal(failed.baseCredited, FEE * 6n);
  assert.equal(failed.refund(required, FEE * 2n), FEE * 10n, 'a round that failed after the draw spends the base fees and the draw reward');

  const done = newRound();
  const v = [0n, 1000000n];
  const reveals = committed(done, [v, v, v, v, v, v]);
  for (const { slot } of reveals.slice(0, 4)) done.fulfill(slot, v, `${CID(slot)}:${SALT}`);
  assert.equal(done.bonusCredited, FEE * 3n * 3n);
  assert.equal(done.refund(required, FEE * 3n), 0n, 'a finished round spends the whole worst case when every fee is at the ceiling');
  assert.equal(done.refund(required + 7n, FEE * 3n), 7n);
});
